'use client';

import { useCallback, useEffect, useMemo, useState } from 'react';
import { ArrowLeftRight, Building2, Plus } from 'lucide-react';
import { formatBrazilianMoneyInput, maskBrazilianMoneyInput } from '@/lib/brazilian-money';
import { formatCurrency } from '@/lib/utils';

type Supplier = { id: string; name: string; document: string; phone: string; email: string };
type Entry = { id: string; type: 'payable' | 'receivable'; supplier_id: string; description: string; due_date: string; amount: number; settled_amount: number; open_amount: number; status: string };
type Data = { suppliers: Supplier[]; entries: Entry[]; settlements: unknown[] };
const empty: Data = { suppliers: [], entries: [], settlements: [] };

export default function FinancialAccounts({ vendorId }: { vendorId: string }) {
  const [data, setData] = useState<Data>(empty); const [message, setMessage] = useState(''); const [supplier, setSupplier] = useState({ name: '', document: '', phone: '', email: '' });
  const [entry, setEntry] = useState({ supplier_id: '', type: 'payable', description: '', due_date: '', amount: '' }); const [settlement, setSettlement] = useState({ supplier_id: '', payable_id: '', receivable_id: '', amount: '', note: '' });
  const load = useCallback(() => fetch(`/api/vendor/financial-accounts?vendor_id=${vendorId}`, { cache: 'no-store' }).then(async response => { const result = await response.json(); if (!response.ok) throw new Error(result.error); setData(result); }).catch(error => setMessage(error instanceof Error ? error.message : 'Erro ao carregar.')), [vendorId]);
  useEffect(() => { load(); }, [load]);
  const save = async (payload: Record<string, unknown>) => { setMessage(''); const response = await fetch('/api/vendor/financial-accounts', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ vendor_id: vendorId, ...payload }) }); const result = await response.json(); if (!response.ok) return setMessage(result.error || 'Erro ao salvar.'); setData(result); setMessage('Salvo com sucesso.'); };
  const openEntries = useMemo(() => data.entries.filter(item => item.open_amount > 0.009), [data.entries]); const supplierName = (id: string) => data.suppliers.find(item => item.id === id)?.name || 'Fornecedor';
  const totalPayable = openEntries.filter(item => item.type === 'payable').reduce((sum, item) => sum + item.open_amount, 0); const totalReceivable = openEntries.filter(item => item.type === 'receivable').reduce((sum, item) => sum + item.open_amount, 0);
  const settleCandidates = openEntries.filter(item => item.supplier_id === settlement.supplier_id); const selectedPayable = settleCandidates.find(item => item.id === settlement.payable_id); const selectedReceivable = settleCandidates.find(item => item.id === settlement.receivable_id); const suggested = Math.min(selectedPayable?.open_amount || 0, selectedReceivable?.open_amount || 0);
  return <div className="space-y-5"><div className="grid gap-4 sm:grid-cols-3">{[['A pagar', totalPayable, 'text-red-600'], ['A receber', totalReceivable, 'text-green-700'], ['Saldo projetado', totalReceivable - totalPayable, 'text-blue-700']].map(([label, value, tone]) => <article key={String(label)} className="rounded-2xl border bg-white p-5 shadow-sm"><p className="font-bold text-gray-500">{label}</p><p className={`mt-2 text-2xl font-black ${tone}`}>{formatCurrency(Number(value))}</p></article>)}</div>
    <div className="grid gap-5 xl:grid-cols-3"><form onSubmit={event => { event.preventDefault(); void save({ action: 'supplier', ...supplier }).then(() => setSupplier({ name: '', document: '', phone: '', email: '' })); }} className="rounded-2xl border bg-white p-5 shadow-sm"><h2 className="flex gap-2 text-xl font-black"><Building2/> Cadastrar fornecedor</h2><div className="mt-4 space-y-3">{[['name','Nome *'],['document','CPF/CNPJ'],['phone','Telefone'],['email','E-mail']].map(([key,label]) => <input key={key} value={supplier[key as keyof typeof supplier]} onChange={event => setSupplier(current => ({ ...current, [key]: event.target.value }))} placeholder={label} className="min-h-11 w-full rounded-xl border-2 px-3"/>)}<button className="min-h-11 w-full rounded-xl bg-gray-950 font-black text-white"><Plus className="inline" size={18}/> Salvar fornecedor</button></div></form>
      <form onSubmit={event => { event.preventDefault(); void save({ action: 'entry', ...entry }).then(() => setEntry(current => ({ ...current, description: '', amount: '' }))); }} className="rounded-2xl border bg-white p-5 shadow-sm"><h2 className="text-xl font-black">Nova conta</h2><div className="mt-4 space-y-3"><select value={entry.supplier_id} onChange={event => setEntry(current => ({ ...current, supplier_id: event.target.value }))} className="min-h-11 w-full rounded-xl border-2 px-3"><option value="">Fornecedor</option>{data.suppliers.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select><select value={entry.type} onChange={event => setEntry(current => ({ ...current, type: event.target.value }))} className="min-h-11 w-full rounded-xl border-2 px-3"><option value="payable">Conta a pagar</option><option value="receivable">Conta a receber</option></select><input value={entry.description} onChange={event => setEntry(current => ({ ...current, description: event.target.value }))} placeholder="Descrição" className="min-h-11 w-full rounded-xl border-2 px-3"/><input type="date" value={entry.due_date} onChange={event => setEntry(current => ({ ...current, due_date: event.target.value }))} className="min-h-11 w-full rounded-xl border-2 px-3"/><input inputMode="numeric" value={entry.amount} onChange={event => setEntry(current => ({ ...current, amount: maskBrazilianMoneyInput(event.target.value) }))} placeholder="Valor 0,00" className="min-h-11 w-full rounded-xl border-2 px-3"/><button className="min-h-11 w-full rounded-xl bg-[#FF6B00] font-black text-white">Cadastrar conta</button></div></form>
      <form onSubmit={event => { event.preventDefault(); void save({ action: 'settle', ...settlement }); }} className="rounded-2xl border border-blue-200 bg-blue-50 p-5 shadow-sm"><h2 className="flex gap-2 text-xl font-black"><ArrowLeftRight/> Encontro de contas</h2><p className="mt-1 text-sm font-bold text-blue-800">Compense um valor a pagar com um valor a receber do mesmo fornecedor.</p><div className="mt-4 space-y-3"><select value={settlement.supplier_id} onChange={event => setSettlement({ supplier_id: event.target.value, payable_id: '', receivable_id: '', amount: '', note: '' })} className="min-h-11 w-full rounded-xl border-2 px-3"><option value="">Fornecedor</option>{data.suppliers.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select><select value={settlement.payable_id} onChange={event => setSettlement(current => ({ ...current, payable_id: event.target.value, amount: '' }))} className="min-h-11 w-full rounded-xl border-2 px-3"><option value="">Conta a pagar</option>{settleCandidates.filter(item => item.type === 'payable').map(item => <option key={item.id} value={item.id}>{item.description} · {formatCurrency(item.open_amount)}</option>)}</select><select value={settlement.receivable_id} onChange={event => setSettlement(current => ({ ...current, receivable_id: event.target.value, amount: '' }))} className="min-h-11 w-full rounded-xl border-2 px-3"><option value="">Conta a receber</option>{settleCandidates.filter(item => item.type === 'receivable').map(item => <option key={item.id} value={item.id}>{item.description} · {formatCurrency(item.open_amount)}</option>)}</select><input inputMode="numeric" value={settlement.amount} onChange={event => setSettlement(current => ({ ...current, amount: maskBrazilianMoneyInput(event.target.value) }))} placeholder={suggested ? `Até ${formatBrazilianMoneyInput(suggested)}` : 'Valor 0,00'} className="min-h-11 w-full rounded-xl border-2 px-3"/><input value={settlement.note} onChange={event => setSettlement(current => ({ ...current, note: event.target.value }))} placeholder="Observação" className="min-h-11 w-full rounded-xl border-2 px-3"/><button className="min-h-11 w-full rounded-xl bg-blue-700 font-black text-white">Realizar encontro</button></div></form></div>
    <section className="rounded-2xl border bg-white p-5 shadow-sm"><h2 className="text-xl font-black">Contas cadastradas</h2><div className="mt-4 overflow-x-auto"><table className="min-w-[760px] w-full text-left"><thead><tr className="border-b text-sm text-gray-500"><th className="p-3">Tipo</th><th>Fornecedor</th><th>Descrição</th><th>Vencimento</th><th>Valor</th><th>Saldo</th><th>Status</th></tr></thead><tbody>{data.entries.map(item => <tr key={item.id} className="border-b"><td className="p-3 font-black">{item.type === 'payable' ? 'A pagar' : 'A receber'}</td><td>{supplierName(item.supplier_id)}</td><td>{item.description}</td><td>{new Date(`${item.due_date}T12:00:00`).toLocaleDateString('pt-BR')}</td><td>{formatCurrency(item.amount)}</td><td className="font-black">{formatCurrency(item.open_amount)}</td><td>{item.status === 'settled' ? 'Compensada' : item.status === 'partial' ? 'Parcial' : 'Aberta'}</td></tr>)}</tbody></table>{data.entries.length === 0 ? <p className="p-5 text-center font-bold text-gray-500">Nenhuma conta cadastrada.</p> : null}</div></section>{message ? <p role="status" className="rounded-xl bg-orange-50 p-3 font-black text-[#8A3E22]">{message}</p> : null}</div>;
}

